contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We implement a receiver so that if C forwards funds to this contract, it can accept them.
    receive() external payable {}

    // The property test: take any amount and call c.go{value: amount}();
    // Assert that after the call, either it reverted, or the owner stayed the same and c has zero balance.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // If we will send Ether, ensure this contract has enough balance to send that amount.
        if (amount > 0) {
            require(address(this).balance >= amount);
        }

        // Read the owner before the call.
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        // Read balance of c before the call (not strictly necessary but allowed).
        uint256 balBefore = address(c).balance;

        bool reverted;
        // Make the state-changing call as a top-level statement and capture whether it reverted.
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read observable state after the call.
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        // General rule: if the call did not revert, the owner must be unchanged and c's balance must be zero.
        // If it reverted, we make no further guarantees here.
        assert(reverted || (ownerAfter == ownerBefore && balAfter == 0));
    }
}

